import{_ as a,o as t,c as o,ao as h}from"./chunks/framework.B7UvRKha.js";const m=JSON.parse('{"title":"The project chat","description":"","frontmatter":{},"headers":[],"relativePath":"guide/chat.md","filePath":"guide/chat.md","lastUpdated":null}'),s={name:"guide/chat.md"};function n(r,e,i,c,l,d){return t(),o("div",null,[...e[0]||(e[0]=[h('<h1 id="The-project-chat" tabindex="-1">The project chat <a class="header-anchor" href="#The-project-chat" aria-label="Permalink to &quot;The project chat {#The-project-chat}&quot;">​</a></h1><p>The Chat drawer (<code>Ctrl+Shift+K</code>) shows the messages of one Slack channel: the channel the selected row&#39;s folder maps to. The records the window holds are listed oldest first, and the newest sits at the bottom. The view follows the newest, so a message that arrives takes the bottom line and lifts the rest. An empty channel shows <code>no messages</code>.</p><p>Each message starts with its own header line: the author&#39;s name, a tag for a post that came from the drawer, a row or a bot, and the time (<code>HH:MM</code> for today, with the date for an earlier day). The text follows as typed.</p><h2 id="Which-channel" tabindex="-1">Which channel <a class="header-anchor" href="#Which-channel" aria-label="Permalink to &quot;Which channel {#Which-channel}&quot;">​</a></h2><p>The hub&#39;s <code>chat.toml</code> maps a folder to a channel; a row whose folder is mapped shows that channel. How the mapping is written is in <a href="/ship-of-tools/dev/ref/config#chat.toml-and-chat-secrets.toml">the chat configuration</a>. The drawer follows the selected row; for a row whose folder is unmapped, or while the hub has no chat, it shows nothing.</p><h2 id="Markup-shows-as-markup" tabindex="-1">Markup shows as markup <a class="header-anchor" href="#Markup-shows-as-markup" aria-label="Permalink to &quot;Markup shows as markup {#Markup-shows-as-markup}&quot;">​</a></h2><p>A message is shown as its poster typed it. Slack&#39;s markup, such as a mention or a link, is shown as the markup text in its own color and is not rendered: a link is not clickable and a mention is not replaced by a name. Text that looks like a header inside a message stays body text.</p><h2 id="When-Slack-is-unreachable" tabindex="-1">When Slack is unreachable <a class="header-anchor" href="#When-Slack-is-unreachable" aria-label="Permalink to &quot;When Slack is unreachable {#When-Slack-is-unreachable}&quot;">​</a></h2><p>The drawer does not show the state of the Slack connection yet, nor why a channel is missing; that is a later change. It keeps the records it holds until a new snapshot replaces them. <code>no messages</code> appears only for a channel that was read whole and holds none.</p><h2 id="Not-yet" tabindex="-1">Not yet <a class="header-anchor" href="#Not-yet" aria-label="Permalink to &quot;Not yet {#Not-yet}&quot;">​</a></h2><p>Posting from the drawer, older pages of history, threads and sharing a selection with the agent are not built yet. Each arrives with its own change, and this page says so when it does.</p>',11)])])}const w=a(s,[["render",n]]);export{m as __pageData,w as default};
